PREFIX qudt: <http://qudt.org/schema/qudt/>

SELECT DISTINCT ?year ?nationalMedianDischarge
WHERE {
  GRAPH <hydroturtle/quadica> {
    ?obs a sosa:Observation ;
         sosa:observedProperty hyobs:DischargeMedian ;
         sosa:hasResult ?result ;
         sosa:resultTime ?rt ;
         sosa:hasFeatureOfInterest ?catchment .
    ?result qudt:numericValue ?nationalMedianDischarge .
    ?rt sosa:resultTime ?rt2 .

    BIND (YEAR(xsd:dateTime(STR(?rt))) AS ?year)

    ?catchment a sosa:Sensor ;
               hyobs:fractionAreaInGermany ?fractionAreaInGermany .

    FILTER(xsd:decimal(?fractionAreaInGermany) = 1)

    ?ltObs a sosa:Observation ;
           sosa:observedProperty hyobs:DischargeMedian ;
           sosa:hasResult ?ltResult ;
           sosa:resultTime ?ltRt ;
           sosa:hasFeatureOfInterest ?ltCatchment .
    ?ltResult qudt:numericValue ?longTermMedianDischarge .
    ?ltCatchment a sosa:Sensor ;
                  hyobs:fractionAreaInGermany ?ltFractionAreaInGermany .
    FILTER(xsd:decimal(?ltFractionAreaInGermany) = 1)

    FILTER(?nationalMedianDischarge < ?longTermMedianDischarge)
  }
}

actual_sparql:
PREFIX hyobs: <https://w3id.org/hmontology/>
PREFIX sosa:  <http://www.w3.org/ns/sosa/>
PREFIX qudt:  <http://qudt.org/schema/qudt/>
PREFIX xsd:   <http://www.w3.org/2001/XMLSchema#>

SELECT ?year ?nationalMedianQ ?longTermMedianQ
WHERE {
  GRAPH <hydroturtle/quadica> 
  {
    {
      SELECT ?year (AVG(xsd:decimal(?val)) AS ?nationalMedianQ)
      WHERE {
        ?obs a sosa:Observation ;
            sosa:observedProperty hyobs:DischargeMedian ;
            sosa:resultTime ?t ;
            sosa:hasResult ?res .
        ?res qudt:numericValue ?val .
        BIND(YEAR(?t) AS ?year)
      }
      GROUP BY ?year
    }
    {
      SELECT (AVG(xsd:decimal(?val2)) AS ?longTermMedianQ)
      WHERE {
        ?obs2 a sosa:Observation ;
              sosa:observedProperty hyobs:DischargeMedian ;
              sosa:hasResult ?res2 .
        ?res2 qudt:numericValue ?val2 .
      }
    }

    FILTER(?nationalMedianQ < ?longTermMedianQ)
  }
}
ORDER BY ?year

PREFIX hyobs:  <https://w3id.org/hmontology/>
PREFIX sosa:   <http://www.w3.org/ns/sosa/>
PREFIX schema: <http://schema.org/>
PREFIX qudt:   <http://qudt.org/schema/qudt/>
PREFIX xsd:    <http://www.w3.org/2001/XMLSchema#>
PREFIX chebi:  <http://purl.obolibrary.org/obo/CHEBI_>

SELECT (COUNT(DISTINCT ?month) AS ?monthsAbove10point5)
WHERE {
  GRAPH <hydroturtle/quadica> {
    ?sensor a sosa:Sensor ;
            schema:name ?stationName. 
    FILTER(lcase(str(?stationName)) = "bw_cks022")

    ?obs a sosa:Observation ;
        sosa:madeBySensor ?sensor ;
        sosa:observedProperty hyobs:SoluteConcentrationFlowNormalizedMean ;
        hyobs:hasAnalyte chebi:17632 ;
        sosa:resultTime ?t ;
        sosa:hasResult ?res .

    ?res qudt:numericValue ?val .

    FILTER(YEAR(?t) = 1997)
    FILTER(xsd:decimal(?val) > 10.5)

    BIND(CONCAT(STR(YEAR(?t)), "-", STR(MONTH(?t))) AS ?month)
  }
}
